dashboard.definition:
{
	"dataSources": {
		"ds_4oNQJMHD": {
			"type": "ds.search",
			"options": {
				"query": "| mcatalog values(vap_ssid) as ssid WHERE index=\"cisco_metrics\" extracted_source=$extracted_source$ AND metric_name=\"mdt_wl_info_vap_ssid\"\n| mvexpand ssid",
				"queryParameters": {
					"sampleRatio": 1
				}
			},
			"name": "SSIDs with clients search"
		},
		"ds_hKZkXDZM": {
			"type": "ds.search",
			"options": {
				"query": "| mstats latest(\"mdt_xe_cpu_stats_one_minute\") prestats=true WHERE \"index\"=\"cisco_metrics\" extracted_source=$extracted_source$ span=60s BY extracted_source\n| timechart latest(\"mdt_xe_cpu_stats_one_minute\") AS Usage span=60s\n| fields - _span*",
				"queryParameters": {
					"sampleRatio": 1
				}
			},
			"name": "CPU Utilization search"
		},
		"ds_0TgrzM3h": {
			"name": "Connected APs search",
			"options": {
				"query": "| mstats latest(\"mdt_wl_info_ap_ip_addr\") as assoc_aps prestats=false WHERE \"index\"=\"cisco_metrics\" extracted_source=$extracted_source$ BY oper_data_wtp_mac\n| stats count",
				"queryParameters": {
					"sampleRatio": 1
				}
			},
			"type": "ds.search"
		},
		"ds_5CDPQxiM": {
			"name": "TX Util by band search",
			"options": {
				"query": "| mstats sum(\"mdt_wl_ap_stats_tx_util_percentage\") prestats=true WHERE \"index\"=\"cisco_metrics\" extracted_source=$extracted_source$ span=1m BY rrm_measurement_radio_slot_id\n| eval band=case(\n    rrm_measurement_radio_slot_id=0, \"2.4 GHz\",\n    rrm_measurement_radio_slot_id=1, \"5 GHz\",\n    rrm_measurement_radio_slot_id=2, \"6 GHz\"\n)\n| timechart sum(\"mdt_wl_ap_stats_tx_util_percentage\") AS tx_util span=1m useother=false BY band",
				"queryParameters": {
					"sampleRatio": 1
				}
			},
			"type": "ds.search"
		},
		"ds_5fscA8dt": {
			"name": "RX Util by Band search",
			"options": {
				"query": "| mstats sum(\"mdt_wl_ap_stats_rx_util_percentage\") prestats=true WHERE \"index\"=\"cisco_metrics\" extracted_source=$extracted_source$ span=1m BY rrm_measurement_radio_slot_id\n| eval band=case(\n    rrm_measurement_radio_slot_id=0, \"2.4 GHz\",\n    rrm_measurement_radio_slot_id=1, \"5 GHz\",\n    rrm_measurement_radio_slot_id=2, \"6 GHz\"\n)\n| timechart sum(\"mdt_wl_ap_stats_rx_util_percentage\") AS rx_util span=1m useother=false BY band",
				"queryParameters": {
					"sampleRatio": 1
				}
			},
			"type": "ds.search"
		},
		"ds_8RPUR6QH": {
			"name": "Bar chart search",
			"options": {
				"query": "| mstats sum(\"mdt_wl_ap_stats_num_assoc_clients\") as assoc_clients prestats=false WHERE \"index\"=\"cisco_metrics\" extracted_source=$extracted_source$ span=60s BY ssid_counters_slot_id\n| eval band=case(\n    ssid_counters_slot_id=0, \"2.4 GHz\",\n    ssid_counters_slot_id=1, \"5 GHz\",\n    ssid_counters_slot_id=2, \"6 GHz\"\n)\n| stats latest(assoc_clients) by band",
				"queryParameters": {
					"sampleRatio": 1
				}
			},
			"type": "ds.search"
		},
		"ds_AtHv0KRb": {
			"name": "Non-Wifi Interferers by Band search",
			"options": {
				"query": "| mstats latest(\"mdt_wl_ap_stats_non_wifi_inter\") prestats=true WHERE \"index\"=\"cisco_metrics\" extracted_source=$extracted_source$ span=1m BY rrm_measurement_radio_slot_id\n| eval band=case(\n    rrm_measurement_radio_slot_id=0, \"2.4 GHz\",\n    rrm_measurement_radio_slot_id=1, \"5 GHz\",\n    rrm_measurement_radio_slot_id=2, \"6 GHz\"\n)\n| timechart latest(\"mdt_wl_ap_stats_non_wifi_inter\") span=1m useother=false BY band\n| fields - _span*",
				"queryParameters": {
					"sampleRatio": 1
				}
			},
			"type": "ds.search"
		},
		"ds_HRW0qhzn": {
			"name": "WLC Memory Usage search",
			"options": {
				"query": "| mstats sum(\"mdt_xe_mem_stats_total_memory\") AS total_memory sum(\"mdt_xe_mem_stats_used_memory\") AS used_memory WHERE index=\"cisco_metrics\" span=5m BY extracted_source\n| stats sum(total_memory) as total_memory, sum(used_memory) as used_memory by extracted_source, _time\n| search extracted_source=$extracted_source$\n| eval pct_used=round((used_memory/total_memory)*100, 2)\n| timechart span=5m avg(pct_used) BY extracted_source",
				"queryParameters": {
					"sampleRatio": 1
				}
			},
			"type": "ds.search"
		},
		"ds_L46xIyeN": {
			"name": "Number of Clients by band - Pie chart search",
			"options": {
				"query": "| mstats latest(\"mdt_wl_ap_stats_num_assoc_clients\") prestats=true WHERE \"index\"=\"cisco_metrics\" span=60s BY ssid_counters_slot_id\n| eval band=case(\n    ssid_counters_slot_id=0, \"2.4 GHz\",\n    ssid_counters_slot_id=1, \"5 GHz\",\n    ssid_counters_slot_id=2, \"6 GHz\"\n)\n| stats latest(mdt_wl_ap_stats_num_assoc_clients) as clients by band",
				"queryParameters": {
					"earliest": "-15m",
					"latest": "now",
					"sampleRatio": 1
				}
			},
			"type": "ds.search"
		},
		"ds_VNFcx863": {
			"name": "wlc_search",
			"options": {
				"query": "| mcatalog values(extracted_source) as wlc WHERE index=\"cisco_metrics\" AND metric_name=\"mdt_wl_info_ap_ip_addr\"\n| mvexpand wlc",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"type": "ds.search"
		},
		"ds_jZoM81tH": {
			"name": "Connected Clients search",
			"options": {
				"query": "| mstats sum(\"mdt_wl_ap_stats_num_assoc_clients\") as assoc_clients prestats=false WHERE \"index\"=\"cisco_metrics\" extracted_source=$extracted_source$ span=60s BY extracted_source\n| stats latest(assoc_clients)",
				"queryParameters": {
					"sampleRatio": 1
				}
			},
			"type": "ds.search"
		},
		"ds_ousGuGxE": {
			"name": "Noise Util by Band search",
			"options": {
				"query": "| mstats latest(\"mdt_wl_ap_stats_rx_noise_channel_utilization\") prestats=true WHERE \"index\"=\"cisco_metrics\" extracted_source=$extracted_source$ span=1m BY rrm_measurement_radio_slot_id\n| eval band=case(\n    rrm_measurement_radio_slot_id=0, \"2.4 GHz\",\n    rrm_measurement_radio_slot_id=1, \"5 GHz\",\n    rrm_measurement_radio_slot_id=2, \"6 GHz\"\n)\n| timechart latest(\"mdt_wl_ap_stats_rx_noise_channel_utilization\") span=1m useother=false BY band\n| fields - _span*",
				"queryParameters": {
					"sampleRatio": 1
				}
			},
			"type": "ds.search"
		},
		"ds_zleSzNCn": {
			"name": "Number of Clients by Band search",
			"options": {
				"query": "| mstats sum(\"mdt_wl_ap_stats_num_assoc_clients\") prestats=true WHERE \"index\"=\"cisco_metrics\" extracted_source=$extracted_source$ span=60s BY ssid_counters_slot_id\n| eval band=case(\n    ssid_counters_slot_id=0, \"2.4 GHz\",\n    ssid_counters_slot_id=1, \"5 GHz\",\n    ssid_counters_slot_id=2, \"6 GHz\"\n)\n| timechart sum(\"mdt_wl_ap_stats_num_assoc_clients\") span=60s BY band",
				"queryParameters": {
					"sampleRatio": 1
				}
			},
			"type": "ds.search"
		}
	},
